const ACTIVE = 'ACTIVE';
const asText = (value) => (value == null ? '' : String(value).trim());
const asNumber = (value, fallback = 0) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};
const truthy = (value) => ['YES', 'TRUE', '1', 'ACTIVE'].includes(asText(value).toUpperCase());
const localDate = (date, timezone) => {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date).filter(({ type }) => type !== 'literal').map(({ type, value }) => [type, value]));
  return `${parts.year}-${parts.month}-${parts.day}`;
};
const localParts = (date, timezone) => Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: timezone, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(date).filter(({ type }) => type !== 'literal').map(({ type, value }) => [type, value]));
const shiftDate = (date, amount) => {
  const shifted = new Date(`${date}T00:00:00.000Z`);
  shifted.setUTCDate(shifted.getUTCDate() + amount);
  return shifted.toISOString().slice(0, 10);
};

function toUtc(date, time, timezone) {
  const [hour, minute] = asText(time).split(':').map(Number);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(asText(date)) || !Number.isInteger(hour) || !Number.isInteger(minute)) return null;
  let guess = Date.UTC(Number(date.slice(0, 4)), Number(date.slice(5, 7)) - 1, Number(date.slice(8, 10)), hour, minute, 0);
  const desired = Date.UTC(Number(date.slice(0, 4)), Number(date.slice(5, 7)) - 1, Number(date.slice(8, 10)), hour, minute, 0);
  for (let index = 0; index < 3; index += 1) {
    const parts = localParts(new Date(guess), timezone);
    const observed = Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day), Number(parts.hour), Number(parts.minute), Number(parts.second));
    guess += desired - observed;
  }
  return new Date(guess);
}

function weekdayAllowed(date, timezone, configured) {
  const days = asText(configured).split(/[|,\s]+/).map((value) => value.toUpperCase()).filter(Boolean);
  if (days.length === 0 || days.includes('*')) return true;
  const weekday = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][date.getUTCDay()];
  const numeric = String(date.getUTCDay());
  return days.includes(weekday) || days.includes(numeric);
}

function activeSession(sessions, branchId) {
  return (sessions ?? []).find((row) => asText(row.branch_id) === asText(branchId) && ['ACTIVE', 'OPEN', 'IN_PROGRESS'].includes(asText(row.status).toUpperCase()));
}

function buildDispatchKey(schedule, businessDate) {
  return [schedule?.schedule_id, schedule?.branch_id, businessDate].map(asText).join(':');
}

function candidateFor(schedule, now) {
  const timezone = asText(schedule.timezone);
  if (!timezone) return null;
  const instant = new Date(now);
  if (Number.isNaN(instant.getTime())) return null;
  const currentDate = localDate(instant, timezone);
  const dates = [currentDate, shiftDate(currentDate, -1)];
  const candidates = dates.filter((date) => weekdayAllowed(new Date(`${date}T12:00:00.000Z`), timezone, schedule.days_of_week)).map((businessDate) => {
    const scheduledAt = toUtc(businessDate, schedule.local_time, timezone);
    const graceEnd = scheduledAt ? new Date(scheduledAt.getTime() + asNumber(schedule.grace_window_minutes) * 60_000) : null;
    return { businessDate, scheduledAt, graceEnd };
  }).filter(({ scheduledAt }) => scheduledAt);
  const due = candidates.find(({ scheduledAt, graceEnd }) => instant >= scheduledAt && instant <= graceEnd);
  if (due) return { ...due, state: 'DUE' };
  const missed = candidates.find(({ scheduledAt, graceEnd }) => instant > graceEnd && scheduledAt <= instant);
  if (missed) return { ...missed, state: 'OUTSIDE_GRACE_WINDOW' };
  return null;
}

function historyBlocks(row, schedule, now) {
  if (!row) return false;
  const status = asText(row.status).toUpperCase();
  if (['CLAIMED', 'RUNNING', 'SUCCESS', 'SKIPPED', 'WARNING'].includes(status)) return true;
  if (status !== 'FAILED') return true;
  const attempts = asNumber(row.attempt_count, 0);
  if (attempts >= asNumber(schedule.retry_limit, 0)) return true;
  const explicitRetryAt = Date.parse(asText(row.retry_at));
  const updatedAt = Date.parse(asText(row.updated_at));
  const retryAt = Number.isFinite(explicitRetryAt)
    ? explicitRetryAt
    : Number.isFinite(updatedAt) ? updatedAt + asNumber(schedule.retry_delay_minutes) * 60_000 : null;
  return Number.isFinite(retryAt) && Date.parse(now) < retryAt;
}

function planDispatch({ now = new Date().toISOString(), schedules = [], branches = [], history = [], activeSessions = [], configSnapshotId = null } = {}) {
  const actions = [];
  for (const schedule of schedules) {
    if (!truthy(schedule.enabled) || asText(schedule.trang_thai).toUpperCase() === 'INACTIVE') continue;
    const candidate = candidateFor(schedule, now);
    if (!candidate) continue;
    const dispatchKey = buildDispatchKey(schedule, candidate.businessDate);
    const previous = (history ?? []).find((row) => asText(row.dispatch_key) === dispatchKey);
    if (historyBlocks(previous, schedule, now)) continue;
    if (candidate.state === 'OUTSIDE_GRACE_WINDOW') {
      actions.push({ kind: 'WARNING', reason: 'OUTSIDE_GRACE_WINDOW', notice_code: 'DISPATCH_OUTSIDE_GRACE_WINDOW', dispatch_key: dispatchKey, schedule_id: asText(schedule.schedule_id), job_code: asText(schedule.job_code), branch_id: asText(schedule.branch_id), business_date: candidate.businessDate, scheduled_at: candidate.scheduledAt.toISOString(), config_snapshot_id: configSnapshotId });
      continue;
    }
    const branch = (branches ?? []).find((row) => asText(row.branch_id) === asText(schedule.branch_id));
    if (!branch || asText(branch.trang_thai).toUpperCase() !== ACTIVE) {
      actions.push({ kind: 'SKIP', reason: 'BRANCH_INACTIVE', notice_code: 'DISPATCH_BRANCH_INACTIVE', dispatch_key: dispatchKey, schedule_id: asText(schedule.schedule_id), job_code: asText(schedule.job_code), branch_id: asText(schedule.branch_id), business_date: candidate.businessDate, config_snapshot_id: configSnapshotId });
      continue;
    }
    const existing = activeSession(activeSessions, schedule.branch_id);
    if (existing) {
      actions.push({ kind: 'SKIP', reason: 'ACTIVE_SESSION_EXISTS', notice_code: 'DISPATCH_ACTIVE_SESSION_EXISTS', dispatch_key: dispatchKey, schedule_id: asText(schedule.schedule_id), job_code: asText(schedule.job_code), branch_id: asText(schedule.branch_id), business_date: candidate.businessDate, session_id: asText(existing.session_id), config_snapshot_id: configSnapshotId });
      continue;
    }
    const attemptCount = asNumber(previous?.attempt_count, 0) + 1;
    actions.push({
      kind: 'DISPATCH',
      status: 'CLAIMED',
      dispatch_key: dispatchKey,
      schedule_id: asText(schedule.schedule_id),
      job_code: asText(schedule.job_code),
      branch_id: asText(schedule.branch_id),
      business_date: candidate.businessDate,
      scheduled_at: candidate.scheduledAt.toISOString(),
      worker_workflow: asText(schedule.worker_workflow),
      attempt_count: String(attemptCount),
      retry_delay_minutes: asText(schedule.retry_delay_minutes),
      retry_limit: asText(schedule.retry_limit),
      config_snapshot_id: configSnapshotId,
    });
  }
  return { actions };
}

function recordHeartbeat({ now = new Date().toISOString(), previous = {}, failure = false, threshold = null } = {}) {
  const limit = asNumber(threshold, 0);
  const oldFailures = asNumber(previous.failure_count, 0);
  if (failure) {
    const failureCount = oldFailures + 1;
    const critical = limit > 0 && failureCount >= limit && asText(previous.critical_notified).toUpperCase() !== 'YES';
    return { heartbeat_at: now, status: 'FAILED', failure_count: failureCount, threshold: limit, critical_notified: critical || asText(previous.critical_notified).toUpperCase() === 'YES' ? 'YES' : 'NO', notice: critical ? 'CRITICAL' : null };
  }
  const recovered = limit > 0 && asText(previous.status).toUpperCase() === 'FAILED' && (asText(previous.critical_notified).toUpperCase() === 'YES' || oldFailures >= limit);
  return { heartbeat_at: now, status: 'HEALTHY', failure_count: 0, threshold: limit, critical_notified: 'NO', notice: recovered ? 'RECOVERY' : null };
}

const claimAsText = (value) => (value == null ? '' : String(value).trim());
const claimStableId = (prefix, value) => `${prefix}-${claimAsText(value).replace(/[^A-Za-z0-9_-]/g, '_')}`;

function prepareDispatchClaim({ action, claimToken, requestId } = {}) {
  const dispatchKey = claimAsText(action?.dispatch_key);
  const token = claimAsText(claimToken);
  if (!dispatchKey || !token) return { ...(action ?? {}), claim_token: token };
  return {
    ...(action ?? {}),
    status: 'CLAIMED',
    claim_token: token,
    operation_id: claimAsText(action.operation_id) || claimStableId('op-dispatch', dispatchKey),
    request_id: claimAsText(requestId) || claimStableId('req-dispatch', `${dispatchKey}:${token}`),
  };
}

function verifyDispatchClaim({ action, persistedRow } = {}) {
  const dispatchKey = claimAsText(action?.dispatch_key);
  const claimToken = claimAsText(action?.claim_token);
  const row = persistedRow ?? {};
  return Boolean(
    dispatchKey &&
    claimToken &&
    claimAsText(row.dispatch_key) === dispatchKey &&
    claimAsText(row.claim_token) === claimToken &&
    ['CLAIMED', 'RUNNING'].includes(claimAsText(row.status).toUpperCase()),
  );
}

const gateway = $('Call Config Gateway').first()?.json ?? {};
const tables = gateway.response?.data?.config_tables ?? {};
const readRows = (name) => {
  try { return $items('Read ' + name).map((item) => item.json).filter((row) => row && Object.keys(row).length > 0); } catch { return []; }
};
const now = new Date().toISOString();
const executionId = typeof $execution !== 'undefined' && $execution.id ? String($execution.id) : now.replace(/[^0-9]/g, '');
const requestEnvelope = $('Prepare Dispatcher Gateway Request').first()?.json?.envelope ?? {};
const claimToken = 'claim-' + executionId;
const heartbeatRows = readRows('HEARTBEAT').sort((left, right) => String(left.heartbeat_at || '').localeCompare(String(right.heartbeat_at || '')));
const threshold = (tables.CONFIG_GLOBAL || []).find((row) => String(row.config_key || '').trim() === 'DISPATCHER_HEARTBEAT_THRESHOLD')?.config_value || null;
const heartbeat = recordHeartbeat({ now, previous: heartbeatRows.at(-1) || {}, failure: gateway.ok !== true, threshold });
const plan = planDispatch({
  now,
  schedules: tables.CONFIG_LICH || [],
  branches: tables.CONFIG_BRANCH || [],
  history: readRows('DISPATCH_HISTORY'),
  activeSessions: readRows('PHIEN_KIEM_KE'),
  configSnapshotId: gateway.response?.config_snapshot_id || null,
});
const heartbeatItem = { kind: 'HEARTBEAT', heartbeat_id: 'dispatcher-' + now, ...heartbeat };
const actions = plan.actions.map((action) => {
  if (action.kind !== 'DISPATCH') return { ...action, heartbeat_id: heartbeatItem.heartbeat_id };
  return {
    ...prepareDispatchClaim({ action, claimToken, requestId: requestEnvelope.request_id }),
    heartbeat_id: heartbeatItem.heartbeat_id,
  };
});
return [heartbeatItem, ...actions].map((json) => ({ json }));

const notificationAsText = (value) => (value == null ? '' : String(value).trim());

function configuredValue(rows, key) {
  return notificationAsText((rows ?? []).find((row) => notificationAsText(row.config_key) === key && notificationAsText(row.trang_thai).toUpperCase() !== 'INACTIVE')?.config_value);
}

function dispatcherNotificationTarget({ configGlobal = [] } = {}) {
  const chatId = configuredValue(configGlobal, 'DISPATCHER_NOTIFICATION_CHAT_ID');
  if (!chatId) return null;
  return {
    chat_id: chatId,
    message_thread_id: configuredValue(configGlobal, 'DISPATCHER_NOTIFICATION_THREAD_ID'),
    branch_id: '',
  };
}

function buildDispatchNotice({ action = {}, configGlobal = [], messages = {}, configVersion = null } = {}) {
  const noticeCode = notificationAsText(action.notice_code);
  if (!noticeCode) return null;
  const operationId = notificationAsText(action.operation_id) || `op-dispatch-${notificationAsText(action.dispatch_key).replace(/[^A-Za-z0-9_-]/g, '_')}`;
  const requestId = notificationAsText(action.request_id) || operationId;
  return {
    error: {
      error_code: noticeCode,
      error_class: 'OPERATIONAL',
      retryable: false,
      message_key: noticeCode,
      message: notificationAsText(messages[noticeCode]) || noticeCode,
      operation_id: operationId,
      request_id: requestId,
      workflow: 'WF04_V2_DISPATCHER',
      node: 'Dispatcher Decision',
      config_version: configVersion,
    },
    context: {
      workflow: 'WF04_V2_DISPATCHER',
      node: 'Dispatcher Decision',
      operation_id: operationId,
      request_id: requestId,
      dispatch_key: notificationAsText(action.dispatch_key),
      branch_id: notificationAsText(action.branch_id),
      config_snapshot_id: notificationAsText(action.config_snapshot_id) || null,
    },
    messages,
    reply_target: dispatcherNotificationTarget({ configGlobal }),
  };
}

